// server/worldmonitor/intelligence/v1/_shared.ts
var CLASSIFY_VALID_LEVELS = ["critical", "high", "medium", "low", "info"];
var CLASSIFY_VALID_CATEGORIES = [
  "conflict",
  "protest",
  "disaster",
  "diplomatic",
  "economic",
  "terrorism",
  "cyber",
  "health",
  "environmental",
  "military",
  "crime",
  "infrastructure",
  "tech",
  "general"
];
function isValidClassifyHit(hit) {
  return CLASSIFY_VALID_LEVELS.includes(hit.level) && CLASSIFY_VALID_CATEGORIES.includes(hit.category);
}
var CLASSIFY_CACHE_PREFIX = "classify:sebuf:v6:";
async function buildClassifyCacheKey(title) {
  return `${CLASSIFY_CACHE_PREFIX}${(await sha256Hex6(title.toLowerCase())).slice(0, 16)}`;
}

